 1   import { registerAgentAutocomplete } from "./autocomplete.js";
 2   import type { ExtensionAPI, RunningAgent } from "./shared.js";
 3   import { registerUserAgentRenderer } from "./transcript.js";
 4   import { handleAgentCommand } from "./runner.js";
 5   import { UserAgentWidget } from "./widget.js";
 6   
 7   export default function userAgent(pi: ExtensionAPI): void {
 8   	const runningAgents = new Set();
 9   	const widget = new UserAgentWidget(runningAgents);
10   	let shuttingDown = false;
11   	let nextAgentNumber = 0;
12   
13   	registerUserAgentRenderer(pi);
14   	registerAgentAutocomplete(pi);
15   
16   	pi.registerCommand("agent", {
17   		description: "Run a background SDK agent with current session context; forwards pi CLI options like --thinking (-i/--isolate for none)",
18   		handler: async (args, ctx) => {
19   			await handleAgentCommand(pi, runningAgents, widget, () => shuttingDown, () => ++nextAgentNumber, "agent", args, `/agent ${args}`.trim(), ctx);
20   		},
21   	});
22   
23   	pi.registerCommand("agent-isolated", {
24   		description: "Alias for /agent -i: run without current session context",
25   		handler: async (args, ctx) => {
26   			await handleAgentCommand(pi, runningAgents, widget, () => shuttingDown, () => ++nextAgentNumber, "agent-isolated", `-i ${args}`, `/agent-isolated ${args}`.trim(), ctx);
27   		},
28   	});
29   
30   	pi.on("session_shutdown", async () => {
31   		shuttingDown = true;
32   		widget.dispose();
33   		const agents = [...runningAgents];
34   		for (const agent of agents) {
35   			void agent.session?.abort();
36   		}
37   		await Promise.allSettled(agents.map((agent) => agent.finished));
38   		for (const agent of agents) {
39   			agent.session?.dispose();
40   		}
41   		runningAgents.clear();
42   	});
43   
44   }
