196 	{
197 		semanticId: "no-prompt-templates",
198 		names: ["--no-prompt-templates", "-np"],
199 		role: "forwarded",
200 		arity: "boolean",
201 		autocomplete: true,
202 		description: "Disable prompt-template loading",
203 	},
204 	{
205 		semanticId: "no-themes",
206 		names: ["--no-themes"],
207 		role: "forwarded",
208 		arity: "boolean",
209 		autocomplete: true,
210 		description: "Disable theme loading",
211 	},
212 	{
213 		semanticId: "no-context-files",
214 		names: ["--no-context-files", "-nc"],
