225 const OPTION_BY_NAME = new Map(AGENT_OPTIONS.flatMap((option) => option.names.map((name) => [name, option] as const)));
226 const QUOTE_PAIRS: Readonly<Record> = { '"': '"', "'": "'", "`": "`", "‘": "’", "“": "”" };
227 
