 23 export async function handleAgentCommand(
 24 	pi: ExtensionAPI,
 25 	runningAgents: Set,
 26 	widget: UserAgentWidget,
 27 	isShuttingDown: () => boolean,
 28 	nextAgentNumber: () => number,
 29 	command: AgentCommandName,
 30 	args: string,
 31 	invocation: string,
 32 	ctx: ExtensionCommandContext,
 33 ): Promise {
 34 	try {
 35 		await startUserAgent(pi, runningAgents, widget, isShuttingDown, nextAgentNumber, command, args, invocation, ctx);
 36 	} catch (error) {
 37 		reportCommandError(pi, command, args, ctx, errorMessage(error));
 38 	}
 39 }
