135 function postUserAgentResult(
136 	pi: ExtensionAPI,
137 	isShuttingDown: () => boolean,
138 	notifyMainAgent: boolean,
139 	message: {
140 		customType: string;
141 		content: string;
142 		display: boolean;
143 		details: AgentCommandDetails;
144 	},
145 ): boolean {
146 	if (isShuttingDown()) return false;
147 	if (notifyMainAgent) {
148 		// Steers into a streaming turn, or triggers an immediate response when idle.
149 		pi.sendMessage(message, { triggerTurn: true });
150 	} else {
151 		// TUI-only session entry: renders in the transcript but never enters the main agent's context.
152 		pi.appendEntry(message.customType, { content: message.content, details: message.details });
153 	}
154 	return true;
155 }
