import { CustomEditor, type ExtensionAPI, type ExtensionContext } from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/index.js";
import {
	decodeKittyPrintable,
	type AutocompleteItem,
	type AutocompleteProvider,
	type AutocompleteSuggestions,
	type EditorComponent,
} from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/node_modules/@earendil-works/pi-tui/dist/index.js";
import { AGENT_OPTIONS, analyzeAgentEditorInput, type OptionCursorExpectation } from "./command-line.js";

type EditorFactory = NonNullable<ReturnType>;
type CompletionModel = { provider: string; id: string; name?: string };
type AutocompleteRuntimeEditor = EditorComponent & {
	forceFileAutocomplete?: (explicitTab?: boolean) => void;
	getCursor?: () => { line: number; col: number };
	isShowingAutocomplete?: () => boolean;
	tryTriggerAutocomplete?: (explicitTab?: boolean) => void;
};

const DECORATED_EDITOR = Symbol.for("pi-user-agents:autocomplete-editor");
const THINKING_LEVELS = ["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const;

type DecoratedEditor = AutocompleteRuntimeEditor & { [DECORATED_EDITOR]?: true };

/** @example getOptionItems(analyzeAgentEditorInput("/agent --thi", 12) as OptionCursorExpectation)[0]?.label // "--thinking " */
export function getOptionItems(expectation: OptionCursorExpectation): AutocompleteItem[] {
	return AGENT_OPTIONS.flatMap((option) => {
		if (!option.autocomplete || expectation.usedSemanticIds.has(option.semanticId)) return [];
		return option.names
			.filter((name) => name.startsWith(expectation.fragment))
			.map((name) => ({
				value: name,
				label: option.arity === "value" ? `${name} <${option.placeholder}>` : name,
				description: option.description,
			}));
	});
}

export function createAgentAutocompleteProvider(current: AutocompleteProvider, getModels: () => readonly CompletionModel[] = () => []): AutocompleteProvider {
	return {
		async getSuggestions(lines, cursorLine, cursorCol, options): Promise {
			if (cursorLine !== 0) return current.getSuggestions(lines, cursorLine, cursorCol, options);
			const expectation = analyzeAgentEditorInput(lines[0] ?? "", cursorCol);
			if (expectation?.kind === "option") {
				const items = getOptionItems(expectation);
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "thinking") {
				const items = THINKING_LEVELS
					.filter((level) => level.startsWith(expectation.fragment))
					.map((level) => ({ value: level, label: level }));
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "model") {
				const items = getModelItems(expectation.fragment, getModels());
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			return current.getSuggestions(lines, cursorLine, cursorCol, options);
		},

		applyCompletion(lines, cursorLine, cursorCol, item, prefix) {
			if (cursorLine !== 0) return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
			const expectation = analyzeAgentEditorInput(lines[0] ?? "", cursorCol);
			if (expectation?.kind === "option" && getOptionItems(expectation).some((candidate) => candidate.value === item.value)) {
				const option = AGENT_OPTIONS.find((candidate) => candidate.names.includes(item.value));
				if (option?.arity === "value" && (option.completionDomain === "path" || option.completionDomain === undefined)) {
					return applyGuardedOptionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
				}
				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
			}
			const thinkingValue = expectation?.kind === "value"
				&& expectation.option.completionDomain === "thinking"
				&& THINKING_LEVELS.some((level) => level === item.value);
			if (thinkingValue && expectation.kind === "value") {
				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
			}
			const modelValue = expectation?.kind === "value"
				&& expectation.option.completionDomain === "model"
				&& getModelItems(expectation.fragment, getModels()).some((model) => model.value === item.value);
			if (modelValue && expectation.kind === "value") {
				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "path") {
				const result = current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
				if (item.label.endsWith("/")) return result;
				const completedLine = result.lines[result.cursorLine] ?? "";
				const cursorAfterSeparator = /\s/.test(completedLine[result.cursorCol] ?? "") ? result.cursorCol + 1 : result.cursorCol;
				return { ...result, cursorCol: cursorAfterSeparator };
			}
			return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
		},

		shouldTriggerFileCompletion(lines, cursorLine, cursorCol) {
			return current.shouldTriggerFileCompletion?.(lines, cursorLine, cursorCol) ?? true;
		},
	};
}

export function registerAgentAutocomplete(pi: ExtensionAPI): void {
	let autocompleteEditorFactory: EditorFactory | undefined;

	function installEditorBridge(ctx: ExtensionContext): void {
		if (ctx.mode !== "tui") return;
		const previousEditorFactory = ctx.ui.getEditorComponent();
		if (autocompleteEditorFactory && previousEditorFactory === autocompleteEditorFactory) return;

		autocompleteEditorFactory = (tui, theme, keybindings) => {
			const editor = previousEditorFactory?.(tui, theme, keybindings) ?? new CustomEditor(tui, theme, keybindings);
			return decorateAutocompleteEditor(
				editor,
				(data) => keybindings.matches(data, "tui.input.tab") || keybindings.matches(data, "tui.select.confirm"),
			);
		};
		ctx.ui.setEditorComponent(autocompleteEditorFactory);
	}

	pi.on("session_start", (_event, ctx) => {
		if (ctx.mode !== "tui") return;
		ctx.ui.addAutocompleteProvider((current) => {
			installEditorBridge(ctx);
			return createAgentAutocompleteProvider(current, () => ctx.modelRegistry.getAll());
		});
		installEditorBridge(ctx);
	});
}

function getModelItems(fragment: string, models: readonly CompletionModel[]): AutocompleteItem[] {
	const query = fragment.toLowerCase();
	return models
		.filter((model) => `${model.provider}/${model.id} ${model.name ?? ""}`.toLowerCase().includes(query))
		.map((model) => {
			const reference = `${model.provider}/${model.id}`;
			return { value: reference, label: reference, description: model.name && model.name !== model.id ? model.name : undefined };
		});
}

function applyCompletionEdit(lines: string[], replacementStart: number, replacementEnd: number, value: string): { lines: string[]; cursorLine: number; cursorCol: number } {
	const line = lines[0] ?? "";
	const before = line.slice(0, replacementStart);
	const after = line.slice(replacementEnd).replace(/^\s+/, "");
	const insertion = `${value} `;
	const nextLines = [...lines];
	nextLines[0] = `${before}${insertion}${after}`;
	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + insertion.length };
}

function applyGuardedOptionEdit(lines: string[], replacementStart: number, replacementEnd: number, optionName: string): { lines: string[]; cursorLine: number; cursorCol: number } {
	const line = lines[0] ?? "";
	const before = line.slice(0, replacementStart);
	const after = line.slice(replacementEnd).replace(/^\s+/, "");
	const insertion = `${optionName} \"\" `;
	const nextLines = [...lines];
	nextLines[0] = `${before}${insertion}${after}`;
	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + optionName.length + 2 };
}

function decorateAutocompleteEditor(editor: T, isCompletionAcceptance: (data: string) => boolean): T {
	const runtimeEditor = editor as DecoratedEditor;
	if (runtimeEditor[DECORATED_EDITOR]) return editor;
	const handleInput = editor.handleInput.bind(editor);
	editor.handleInput = (data) => {
		const getCursor = runtimeEditor.getCursor;
		if (typeof getCursor !== "function") throw new Error("pi-user-agents autocomplete requires editor.getCursor()");
		const beforeCursor = getCursor.call(editor);
		const beforeExpectation = beforeCursor.line === 0 ? analyzeAgentEditorInput(editor.getText(), beforeCursor.col) : undefined;
		const wasShowingAutocomplete = runtimeEditor.isShowingAutocomplete?.call(editor) ?? false;
		const printableCharacter = decodeKittyPrintable(data) ?? (data.length === 1 && data.charCodeAt(0) >= 32 ? data : undefined);
		handleInput(data);

		const cursor = getCursor.call(editor);
		if (cursor.line !== 0) return;
		const expectation = analyzeAgentEditorInput(editor.getText(), cursor.col);
		const typedOptionDash = printableCharacter === "-" && expectation?.kind === "option";
		const acceptedChainedOption = wasShowingAutocomplete
			&& isCompletionAcceptance(data)
			&& beforeExpectation?.kind === "option"
			&& expectation?.kind === "value"
			&& (expectation.option.completionDomain === "thinking"
				|| expectation.option.completionDomain === "model"
				|| expectation.option.completionDomain === "path");
		const acceptedPathDirectory = wasShowingAutocomplete
			&& isCompletionAcceptance(data)
			&& beforeExpectation?.kind === "value"
			&& beforeExpectation.option.completionDomain === "path"
			&& expectation?.kind === "value"
			&& expectation.option.completionDomain === "path";
		if (!typedOptionDash && !acceptedChainedOption && !acceptedPathDirectory) return;

		const pathCompletion = acceptedPathDirectory || (acceptedChainedOption && expectation?.kind === "value" && expectation.option.completionDomain === "path");
		if (pathCompletion) {
			const forceFileAutocomplete = runtimeEditor.forceFileAutocomplete;
			if (typeof forceFileAutocomplete !== "function") throw new Error("pi-user-agents autocomplete requires editor.forceFileAutocomplete()");
			forceFileAutocomplete.call(editor, false);
			return;
		}
		const triggerAutocomplete = runtimeEditor.tryTriggerAutocomplete;
		if (typeof triggerAutocomplete !== "function") throw new Error("pi-user-agents autocomplete requires editor.tryTriggerAutocomplete()");
		triggerAutocomplete.call(editor, false);
	};
	runtimeEditor[DECORATED_EDITOR] = true;
	return editor;
}

