		modelRegistry: { getAll: () => models },
		ui,
	} as unknown as ExtensionContext;

	for (const handler of sessionStartHandlers) {
		await handler({ type: "session_start", reason: "startup" }, context);
	}

	const tui = {
		terminal: { columns: 120, rows: 40 },
		requestRender(): void {},
	} as unknown as TUI;
	const editorTheme: EditorTheme = {
		borderColor: (text) => text,
		selectList: {
			selectedPrefix: (text) => text,
			selectedText: (text) => text,
			description: (text) => text,
			scrollInfo: (text) => text,
			noMatch: (text) => text,
		},
	};
	const keybindings = new KeybindingsManager();
	editor = editorFactory?.(tui, editorTheme, keybindings) ?? new CustomEditor(tui, editorTheme, keybindings);
	const provider = autocompleteProviderFactories.reduce(
		(current, factory) => factory(current),
		new CombinedAutocompleteProvider(commands, cwd),
	);
	editor.setAutocompleteProvider?.(provider);
	const runtimeEditor = editor as EditorHarness["editor"];

	const render = () => runtimeEditor.render(100).join("\n").replace(ANSI_SEQUENCE, "");
	return {
		editor: runtimeEditor,
		press(data: string): void {
			runtimeEditor.handleInput(data);
		},
		render,
		type(text: string): void {
			for (const character of text) runtimeEditor.handleInput(character);
		},
		async waitForAutocomplete(): Promise {
			await waitUntil(() => runtimeEditor.isShowingAutocomplete(), 500);
		},
		async waitForRender(predicate: (rendered: string) => boolean): Promise {
			await waitUntil(() => predicate(render()), 500);
		},
	};
}

async function waitUntil(condition: () => boolean, timeoutMilliseconds: number): Promise {
	const deadline = Date.now() + timeoutMilliseconds;
	while (!condition()) {
		if (Date.now() >= deadline) throw new Error(`Autocomplete did not become visible within ${timeoutMilliseconds}ms`);
		await new Promise((resolve) => setTimeout(resolve, 5));
	}
}

