import {
	CustomEditor,
	type ExtensionAPI,
	type ExtensionContext,
	type RegisteredCommand,
} from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/index.js";
import { KeybindingsManager } from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/core/keybindings.js";
import {
	CombinedAutocompleteProvider,
	type AutocompleteProvider,
	type EditorComponent,
	type EditorTheme,
	type SlashCommand,
	type TUI,
} from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/node_modules/@earendil-works/pi-tui/dist/index.js";
import userAgent from "../index.ts";

export type HarnessModel = { provider: string; id: string; name?: string };

export type EditorHarness = {
	editor: EditorComponent & {
		getCursor(): { line: number; col: number };
		isShowingAutocomplete(): boolean;
	};
	press(data: string): void;
	render(): string;
	type(text: string): void;
	waitForAutocomplete(): Promise;
	waitForAutocompleteToRemainHidden(): Promise;
	waitForRender(predicate: (rendered: string) => boolean): Promise;
};

type SessionStartHandler = (event: { type: "session_start"; reason: "startup" }, ctx: ExtensionContext) => Promise | void;
type AutocompleteProviderFactory = (current: AutocompleteProvider) => AutocompleteProvider;
type EditorFactory = NonNullable<ReturnType>;

const ANSI_SEQUENCE = /\x1b\[[0-?]*[ -/]*[@-~]/g;

export async function createEditorHarness(cwd: string = process.cwd(), models: readonly HarnessModel[] = []): Promise {
	const commands: SlashCommand[] = [];
	const sessionStartHandlers: SessionStartHandler[] = [];
	const autocompleteProviderFactories: AutocompleteProviderFactory[] = [];
	let editorFactory: EditorFactory | undefined;
	let editor: EditorComponent | undefined;

	const pi = {
		on(event: string, handler: unknown): void {
			if (event === "session_start") sessionStartHandlers.push(handler as SessionStartHandler);
		},
		registerCommand(name: string, options: Omit): void {
			commands.push({ name, description: options.description, getArgumentCompletions: options.getArgumentCompletions });
		},
		registerMessageRenderer(): void {},
		registerEntryRenderer(): void {},
		getCommands: () => [],
	} as unknown as ExtensionAPI;

	userAgent(pi);

	const ui = {
		addAutocompleteProvider(factory: AutocompleteProviderFactory): void {
			autocompleteProviderFactories.push(factory);
		},
		getEditorComponent(): EditorFactory | undefined {
			return editorFactory;
		},
		setEditorComponent(factory: EditorFactory | undefined): void {
			editorFactory = factory;
		},
		getEditorText(): string {
			return editor?.getText() ?? "";
		},
		theme: {
			fg: (_color: string, text: string) => text,
		},
	} as unknown as ExtensionContext["ui"];
	const context = {
		cwd,
		hasUI: true,
		mode: "tui",
		modelRegistry: { getAll: () => models },
		ui,
	} as unknown as ExtensionContext;

	for (const handler of sessionStartHandlers) {
		await handler({ type: "session_start", reason: "startup" }, context);
	}

	const tui = {
		terminal: { columns: 120, rows: 40 },
		requestRender(): void {},
	} as unknown as TUI;
	const editorTheme: EditorTheme = {
		borderColor: (text) => text,
		selectList: {
			selectedPrefix: (text) => text,
			selectedText: (text) => text,
			description: (text) => text,
			scrollInfo: (text) => text,
			noMatch: (text) => text,
		},
	};
	const keybindings = new KeybindingsManager();
	editor = editorFactory?.(tui, editorTheme, keybindings) ?? new CustomEditor(tui, editorTheme, keybindings);
	const provider = autocompleteProviderFactories.reduce(
		(current, factory) => factory(current),
		new CombinedAutocompleteProvider(commands, cwd),
	);
	editor.setAutocompleteProvider?.(provider);
	const runtimeEditor = editor as EditorHarness["editor"];

	const render = () => runtimeEditor.render(100).join("\n").replace(ANSI_SEQUENCE, "");
	return {
		editor: runtimeEditor,
		press(data: string): void {
			runtimeEditor.handleInput(data);
		},
		render,
		type(text: string): void {
			for (const character of text) runtimeEditor.handleInput(character);
		},
		async waitForAutocomplete(): Promise {
			await waitUntil(() => runtimeEditor.isShowingAutocomplete(), 500);
		},
		async waitForAutocompleteToRemainHidden(): Promise {
			const deadline = Date.now() + 50;
			while (Date.now() < deadline) {
				if (runtimeEditor.isShowingAutocomplete()) throw new Error(`Expected autocomplete to remain hidden.\nRendered editor:\n${render()}`);
				await new Promise((resolve) => setTimeout(resolve, 5));
			}
		},
		async waitForRender(predicate: (rendered: string) => boolean): Promise {
			await waitUntil(() => predicate(render()), 500);
		},
	};
}

async function waitUntil(condition: () => boolean, timeoutMilliseconds: number): Promise {
	const deadline = Date.now() + timeoutMilliseconds;
	while (!condition()) {
		if (Date.now() >= deadline) throw new Error(`Autocomplete did not become visible within ${timeoutMilliseconds}ms`);
		await new Promise((resolve) => setTimeout(resolve, 5));
	}
}

