const OPTION_BY_NAME = new Map(
	AGENT_OPTIONS.flatMap((option) => option.names.map((name) => [name, option] as const)),
);
const QUOTE_PAIRS: Readonly<Record> = {
	'"': '"',
	"'": "'",
	"`": "`",
	"‘": "’",
	"“": "”",
};

